// IA FALSA, so para o teste local. Nao contacta ninguem.
// Guarda cada pedido em teste/saida/ e devolve respostas de exemplo fixas (escritas a mao, a 15/11/2026),
// para verificar o circuito: pedido montado, recomendacao marcada, roteiro a partir da abertura escolhida.
const fs = require('fs');
const path = require('path');
const saida = path.join(__dirname, '..', '..', '..', '..', 'saida');
const exemplos = require(path.join(__dirname, '..', '..', '..', '..', 'respostas-de-exemplo.js'));
let n = 0;

class Anthropic {
  constructor() {
    this.messages = {
      create: async (params) => {
        n += 1;
        const ferramenta = params.tools[0].name;
        const pedido = params.messages[0].content;
        const nome = `${String(n).padStart(2, '0')}-${process.env.CENARIO || 'teste'}-${ferramenta}.txt`;
        fs.writeFileSync(path.join(saida, nome), `=== SYSTEM ===\n${params.system}\n\n=== PEDIDO ===\n${pedido}\n`);
        let input;
        if (ferramenta === 'devolver_textos') input = { textos: JSON.parse(pedido) };
        else if (ferramenta === 'entregar_ganchos') input = /Receita R3/.test(params.system) ? exemplos.aberturasR3 : exemplos.aberturas;
        else if (ferramenta === 'entregar_roteiro') input = /ABERTURA ESCOLHIDA \(sessao\)/.test(pedido) ? exemplos.roteiroR3 : exemplos.roteiroCuriosidade;
        return { content: [{ type: 'tool_use', name: ferramenta, input }] };
      },
    };
  }
}
module.exports = Anthropic;
module.exports.default = Anthropic;
